question:
Ниже приведён фрагмент программы. Чему равно sum, если n = 6, а начальное значение всех элементов массива a равно нулю?

Pascal
read(n);
for i := 1 to n do
  for x := 1 to i do
    for y := 1 to n − i + 1 do
      a[x, y] := a[x, y] + 1;

sum := 0;
for x := 1 to n do
  for y := 1 to n do
    sum := sum + a[x, y];
writeln(sum);

C++
cin >> n;
for (i = 1; i <= n; i++)
  for (x = 1; x <= i; x++)
    for (y = 1; y <= n − i + 1; y++)
      a[x][y] += 1;

sum = 0;
for (x = 1; x <= n; x++)
  for (y = 1; y <= n; y++)
    sum += a[x][y];
cout << sum;
